def _linear_residual_bound(points):
    """对整段做稳健直线拟合，返回 (残差上界, 内点数)。"""
    if len(points) < 3:
        return float("inf"), len(points)
    _, _, inliers, bound = _robust_linear(points, DEFAULT_TOL_MS)
    return bound, len(inliers)


def _partition(points, tol_ms):
    """返回区段下标范围列表 [(lo, hi), ...]。"""
    # 斜率跳变只在“两侧各自都是好直线”时才采纳，避免把噪声误判成大量断点
    raw_cuts = _slope_jump_cuts(points)
    cuts = []
    for cut in raw_cuts:
        left_bound, left_n = _linear_residual_bound(points[:cut])
        right_bound, right_n = _linear_residual_bound(points[cut:])
        if (
            left_n >= 3
            and right_n >= 3
            and left_bound <= tol_ms
            and right_bound <= tol_ms
        ):
            cuts.append(cut)
    ranges = []
    start = 0
    for cut in cuts + [len(points)]:
        ranges.append((start, cut))
        start = cut

